// Des: Tests for ru-smar-adap: argv, validation, chain fallback with a mock echo tool
// Flo: pure helpers > run echo as the AI > first tool missing, second answers > none answers
// I/O: strings > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const builtin = @import("builtin"); const ai = @import("ru-smar-adap.zig"); const conf = @import("cf-conf-load.zig"); const data = @import("st-stat-data.zig"); const T = std.testing;
const ECHO_EXE = if (builtin.os.tag == .windows) "cmd.exe" else "echo";
const ECHO_ARG: []const []const u8 = if (builtin.os.tag == .windows) &.{ "/c", "echo", "{p}" } else &.{"{p}"};
fn aok() conf.Conf { var cfg: conf.Conf = .{}; cfg.smar_mode_enab = true; cfg.smar_time_secs = 20; return cfg; }
test "argv puts the prompt where {p} is and keeps other args" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const argv = try ai.argvOf(aren.allocator(), "claude", &.{ "-p", "{p}", "-x" }, "hello world"); try T.expectEqual(@as(usize, 4), argv.len); try T.expectEqualStrings("claude", argv[0]); try T.expectEqualStrings("hello world", argv[2]); try T.expectEqualStrings("-x", argv[3]); }
test "clean trims and rejects empty, too long, control chars, bad utf8" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); try T.expectEqualStrings("ok then", try ai.clean(aren.allocator(), "  ok then \r\n")); try T.expectError(error.AiFail, ai.clean(aren.allocator(), "  \n ")); try T.expectError(error.AiFail, ai.clean(aren.allocator(), "a\x07b")); try T.expectError(error.AiFail, ai.clean(aren.allocator(), "\xff\xfe")); const big = try aren.allocator().alloc(u8, 1001); @memset(big, 'a'); try T.expectError(error.AiFail, ai.clean(aren.allocator(), big)); try T.expectEqual(@as(usize, 1000), (try ai.clean(aren.allocator(), big[0..1000])).len); try T.expectEqualStrings("line1\nline2", try ai.clean(aren.allocator(), "line1\nline2")); }
test "prompt lists the history with owner and them labels" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const hist = [_]data.Msgz{ .{ .who = "them", .body = "price?", .ts = 0 }, .{ .who = "me", .body = "100k", .ts = 0 } }; const prom = try ai.promptOf(aren.allocator(), &hist); try T.expect(std.mem.find(u8, prom, "Them: price?\nOwner: 100k\n") != null); try T.expect(std.mem.endsWith(u8, prom, "next reply from the owner.")); }
test "mock tool answers: echo returns the prompt text" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); var cfg = aok(); cfg.smar_clau_exec = ECHO_EXE; cfg.smar_clau_argz = ECHO_ARG; const txt = try ai.ask(aren.allocator(), T.io, cfg, "HelloMock"); try T.expectEqualStrings("HelloMock", txt); }
test "chain falls back when the first tool is missing" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); var cfg = aok(); cfg.smar_clau_exec = "zz-no-such-ai-tool-za"; cfg.smar_llam_exec = ECHO_EXE; cfg.smar_llam_argz = ECHO_ARG; const txt = try ai.ask(aren.allocator(), T.io, cfg, "second_tool"); try T.expectEqualStrings("second_tool", txt); }
test "no tool answers is AiFail, chain order is respected" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); var cfg = aok(); cfg.smar_clau_exec = "zz-no-such-ai-tool-za"; cfg.smar_llam_exec = "zz-no-such-ai-tool-zb"; try T.expectError(error.AiFail, ai.ask(aren.allocator(), T.io, cfg, "x")); var only = aok(); only.smar_chai_orde = &.{"llam"}; only.smar_clau_exec = ECHO_EXE; only.smar_clau_argz = ECHO_ARG; only.smar_llam_exec = "zz-no-such-ai-tool-zb"; try T.expectError(error.AiFail, ai.ask(aren.allocator(), T.io, only, "x")); }
test "off by default: draft refuses unless smar_mode_enab" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const cfg: conf.Conf = .{}; try T.expect(!cfg.smar_mode_enab); try T.expectError(error.AiFail, ai.draft(aren.allocator(), T.io, cfg, &.{})); }
